module bfs_tree (  
    input clk,  
    input reset,  
    input start,  
    input [7:0] node_value,  
    input node_valid,  
    output reg [7:0] bfs_output,  
    output reg done  
);  
    reg [7:0] queue [15:0];  
    reg [3:0] head, tail;  
    reg [3:0] count;  
    reg [3:0] state;  
    parameter IDLE = 0, ENQUEUE = 1, DEQUEUE = 2, OUTPUT = 3;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            head <= 0;  
            tail <= 0;  
            count <= 0;  
            state <= IDLE;  
            done <= 0;  
        end else begin  
            case (state)  
                IDLE: begin  
                    if (start) begin  
                        state <= ENQUEUE;  
                    end  
                end  
                ENQUEUE: begin  
                    if (node_valid && count < 16) begin  
                        queue[tail] <= node_value;  
                        tail <= tail + 1;  
                        count <= count + 1;  
                    end  
                    if (count > 0) begin  
                        state <= DEQUEUE;  
                    end  
                end  
                DEQUEUE: begin  
                    bfs_output <= queue[head];  
                    head <= head + 1;  
                    count <= count - 1;  
                    if (count == 0) begin  
                        state <= OUTPUT;  
                    end  
                end  
                OUTPUT: begin  
                    done <= 1;  
                    state <= IDLE;  
                end  
            endcase  
        end  
    end  
endmodule

