    reg [4:0] y1, y2; // Previous outputs

    always @* begin
        // Implementing the filter output equation: y[n] = b0*x[n] + a1*y[n-1] + a2*y[n-2]
        signal_out = b0 * signal_in + a1 * y1 + a2 * y2;
        // Update previous values
        x2 = x1;
        x1 = signal_in;
        y2 = y1;
        y1 = signal_out;
    end
endmodule

