module dram_cell (  
    input wire D,  
    input wire WE,  
    input wire RE,  
    output reg Q  
);  

    reg stored_value;  

    always @(posedge WE or posedge RE) begin  
        if (WE)  
            stored_value <= D;  
        if (RE)  
            Q <= stored_value;  
    end  

    // Retain the value on Q when neither WE nor RE are active  
    always @(*) begin  
        if (!WE && !RE)  
            Q <= stored_value;  
    end  
endmodule

module eeprom_cell (  
    input [3:0] D,  
    input WE,  
    output reg [3:0] Q  
);  
    always @(*) begin  
        if (WE)  
            Q = D;  
    end  
endmodule

