module Reed_Solomon_Encoder (
    input clk,
    input rst,
    input [3:0] data_in,
    input data_valid,
    output reg [5:0] codeword_out,
    output reg codeword_valid
);
    reg [3:0] data_buffer [0:3];
    reg [1:0] count;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            count <= 0;
            codeword_valid <= 0;
            codeword_out <= 0;
        end else if (data_valid) begin
            data_buffer[count] <= data_in;
            count <= count + 1;
            if (count == 3) begin
                // Simple Reed-Solomon encoding logic (for demonstration)
                codeword_out <= {data_buffer[0] ^ data_buffer[1], data_buffer[2] ^ data_buffer[3]};
                codeword_valid <= 1;
            end
        end
    end
endmodule

