        forever #5 clk = ~clk;
    end

        task reset_dut;

        begin
            reset = 1;
            channel1_req = 0;
            channel2_req = 0;
            repeat(2) @(posedge clk);
            reset = 0;
            @(posedge clk);
        end
        endtask
    task testcase001;

        begin
            test_num = 1;
            $display("Testcase %03d: Channel 1 Single Request", test_num);
            reset_dut();

            @(posedge clk);
            channel1_req = 1;


            fork
                begin : wait_done1
                    wait(channel1_done == 1);
                    disable timeout1;
                end
                begin : timeout1
                    repeat(50) @(posedge clk);
                    $display("Timeout waiting for channel1_done");
                    disable wait_done1;
                end
            join

            channel1_req = 0;
            repeat(2) @(posedge clk);
            #1;

