module i2c_controller(
    input wire clk,
    input wire reset,
    input wire start,
    input wire stop,
    input wire [7:0] data_in,
    output reg sda,
    output reg scl,
    output reg ack,
    output reg ready
);

    reg [3:0] state;
    reg [3:0] bit_count;

    localparam IDLE = 0, START = 1, SEND = 2, STOP = 3;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
            sda <= 1;
            scl <= 1;
            ack <= 0;
            ready <= 1;
            bit_count <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (start) begin
                        sda <= 0; // Start condition
                        scl <= 1;
                        state <= START;
                        ready <= 0;
                        bit_count <= 0;
                    end
                end
                START: begin
                    scl <= 0; // Prepare to send data
                    sda <= data_in[7 - bit_count]; // Send MSB first
                    state <= SEND;
                end
                SEND: begin
                    scl <= 1; // Clock high
                    if (bit_count < 7) begin
                        bit_count <= bit_count + 1;
                        scl <= 0; // Clock low
                        sda <= data_in[7 - bit_count]; // Send next bit
                    end else begin
                        bit_count <= 0;
                        state <= STOP; // Finished sending data
                    end
                end
                STOP: begin
                    scl <= 1; // Prepare to stop
                    sda <= 1; // Stop condition
                    ack <= 1; // Acknowledge signal
                    state <= IDLE;
                    ready <= 1; // Indicate ready for new transmission
                end
            endcase
        end
    end
endmodule

