module uart_transmitter(  
    input clk,  
    input rst,  
    input start_tx,  
    input [7:0] data_in,  
    output reg tx,  
    output reg busy  
);  
    reg [3:0] bit_count;  
    reg [9:0] shift_reg;  
    reg [1:0] state;  

    localparam IDLE = 2'b00,  
               START = 2'b01,  
               TRANSMIT = 2'b10,  
               STOP = 2'b11;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            tx <= 1;  
            busy <= 0;  
            state <= IDLE;  
            bit_count <= 0;  
        end else begin  
            case (state)  
                IDLE: begin  
                    if (start_tx) begin  
                        shift_reg <= {1'b1, data_in, 1'b0}; // stop, data, start  
                        bit_count <= 0;  
                        busy <= 1;  
                        state <= START;  
                    end  
                end  
                START: begin  
                    tx <= shift_reg[0];  
                    state <= TRANSMIT;  
                end  
                TRANSMIT: begin  
                    if (bit_count < 8) begin  
                        tx <= shift_reg[bit_count + 1];  
                        bit_count <= bit_count + 1;  
                    end else begin  
                        state <= STOP;  
                    end  
                end  
                STOP: begin  
                    tx <= 1;  
                    busy <= 0;  
                    state <= IDLE;  
                end  
            endcase  
        end  
    end  
endmodule

