module rsa_encrypt (
    input wire clk,
    input wire reset,
    input wire [31:0] plaintext,
    input wire [31:0] e,
    input wire [31:0] n,
    output reg [31:0] ciphertext
);

reg [31:0] intermediate;
reg [4:0] counter;

always @(posedge clk or posedge reset) begin
    if (reset) begin
        ciphertext <= 32'b0;
        intermediate <= 32'b0;
        counter <= 5'b0;
    end else begin
        if (counter < e) begin
            intermediate <= (intermediate * plaintext) % n;
            counter <= counter + 1;
        end else begin
            ciphertext <= intermediate;
            intermediate <= 32'b0; // Reset for next operation
            counter <= 5'b0; // Reset counter
        end
    end
end

endmodule

