module ofdm_modulator (  
    input clk,  
    input rst_n,  
    input [7:0] data_in,  
    output reg [63:0] ofdm_out  
);  
    reg [7:0] data_reg [0:7];  
    reg [2:0] count;  

    always @(posedge clk or negedge rst_n) begin  
        if (!rst_n) begin  
            count <= 0;  
            ofdm_out <= 0;  
        end else if (count < 8) begin  
            data_reg[count] <= data_in;  
            count <= count + 1;  
