            // Simple IFFT emulation (for illustration purposes)  
            ofdm_out <= {data_reg[7], data_reg[6], data_reg[5], data_reg[4],  
                          data_reg[3], data_reg[2], data_reg[1], data_reg[0]};  
        end  
    end  
endmodule

