module md5_padding (
    input clk,
    input rst,
    input [511:0] msg,
    output reg [127:0] hash
);
    reg [31:0] words [15:0];
    reg [127:0] h; // Intermediate hash value

    initial begin
        h = 128'h67452301EFCDAB8998BADCFE10325476; // MD5 initial hash values
    end

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            hash <= 128'h0;
            h <= 128'h67452301EFCDAB8998BADCFE10325476; // Reset to initial values
        end else begin
            // Divide the input message into 16 words
            words[0] <= msg[511:480];
            words[1] <= msg[479:448];
            words[2] <= msg[447:416];
            words[3] <= msg[415:384];
            words[4] <= msg[383:352];
            words[5] <= msg[351:320];
            words[6] <= msg[319:288];
            words[7] <= msg[287:256];
            words[8] <= msg[255:224];
            words[9] <= msg[223:192];
            words[10] <= msg[191:160];
            words[11] <= msg[159:128];
            words[12] <= msg[127:96];
            words[13] <= msg[95:64];
            words[14] <= msg[63:32];
            words[15] <= msg[31:0];

            // Simplified processing of the words (not complete MD5)
            h[31:0] <= (h[31:0] + words[0]) ^ (h[63:32] ^ words[1]);
            h[63:32] <= (h[63:32] + words[2]) ^ (h[95:64] ^ words[3]);
            h[95:64] <= (h[95:64] + words[4]) ^ (h[127:96] ^ words[5]);
            h[127:96] <= (h[127:96] + words[6]) ^ (h[31:0] ^ words[7]);

            hash <= h; // Assign the final hash output
        end
    end
endmodule

module linear_regression (
    input [15:0] x0, y0,
    input [15:0] x1, y1,
    input [15:0] x2, y2,
    input [15:0] x3, y3,
    input [15:0] x4, y4,
    output reg [15:0] a, b
);
    integer sum_x, sum_y, sum_xy, sum_xx;
    integer n;

    always @(*) begin
        sum_x = x0 + x1 + x2 + x3 + x4;
        sum_y = y0 + y1 + y2 + y3 + y4;
        sum_xy = (x0*y0) + (x1*y1) + (x2*y2) + (x3*y3) + (x4*y4);
        sum_xx = (x0*x0) + (x1*x1) + (x2*x2) + (x3*x3) + (x4*x4);
        n = 5;

        // Calculate coefficients a and b
        a = (n * sum_xy - sum_x * sum_y) / (n * sum_xx - sum_x * sum_x);
        b = (sum_y - a * sum_x) / n;
    end
endmodule

module dma_controller (  
    input clk,  
    input reset,  
    input req1,  
    input req2,  
    output reg ack1,  
    output reg ack2,  
    output reg [7:0] data  
);  
    reg [1:0] state;  
    parameter IDLE = 2'b00, TRANSFERRING1 = 2'b01, TRANSFERRING2 = 2'b10;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            state <= IDLE;  
            ack1 <= 0;  
            ack2 <= 0;  
            data <= 8'd0;  
        end else begin  
            case (state)  
                IDLE: begin  
                    ack1 <= 0;  
                    ack2 <= 0;  
                    if (req1) begin  
                        state <= TRANSFERRING1;  
                    end else if (req2) begin  
                        state <= TRANSFERRING2;  
                    end  
                end  
                TRANSFERRING1: begin  
                    ack1 <= 1;  
                    data <= 8'hAA; // Example data for channel 1  
                    if (!req1) begin  
                        state <= IDLE;  
                    end  
                end  
                TRANSFERRING2: begin  
                    ack2 <= 1;  
                    data <= 8'hBB; // Example data for channel 2  
                    if (!req2) begin  
                        state <= IDLE;  
                    end  
                end  
            endcase  
        end  
    end  
endmodule

