module sample_rate_converter (
    input wire clk,
    input wire rst,
    input wire [7:0] data_in,
    output reg [7:0] data_out
);
    reg [1:0] count;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            count <= 0;
            data_out <= 0;
        end else begin
            count <= count + 1;
            if (count == 2) begin
                data_out <= data_in;
                count <= 0;
            end
        end
    end
endmodule

