module ARQ_System(
    input wire clk,
    input wire rst,
    input wire [4:0] data_in,
    output reg [4:0] data_out,
    output reg ack,
    output reg resend
);
    parameter TIMEOUT = 5;
    reg [2:0] state;
    reg [2:0] timeout_counter;

    parameter IDLE = 3'b000, SEND_DATA = 3'b001, WAIT_ACK = 3'b010, TIMEOUT_STATE = 3'b011;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state <= IDLE;
            data_out <= 5'b00000;
            ack <= 0;
            resend <= 0;
            timeout_counter <= 0;
        end else begin
            case (state)
                IDLE: begin
                    data_out <= data_in;
                    state <= SEND_DATA;
                end

                SEND_DATA: begin
                    ack <= 0;
                    resend <= 0;
                    timeout_counter <= 0;
                    state <= WAIT_ACK;
                end

                WAIT_ACK: begin
                    if (timeout_counter < TIMEOUT) begin
                        timeout_counter <= timeout_counter + 1;
                    end else begin
                        state <= TIMEOUT_STATE;
                    end
                end

                TIMEOUT_STATE: begin
                    resend <= 1;
                    state <= IDLE;
                end

                default: state <= IDLE;
            endcase

            // Acknowledgment logic (for simulation purposes)
            if (data_out == data_in) begin // simulating correct reception
                ack <= 1;
                timeout_counter <= 0;
                state <= IDLE;
            end
        end
    end
endmodule

