module round_robin_arbiter (
    input wire clk,
    input wire reset,
    input wire req0,
    input wire req1,
    output reg grant0,
    output reg grant1
);
    reg last_granted;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            grant0 <= 1'b0;
            grant1 <= 1'b0;
            last_granted <= 1'b0;
        end else begin
            if (req0 && !grant1 && last_granted == 1'b1) begin
                grant0 <= 1'b1;
                grant1 <= 1'b0;
                last_granted <= 1'b0;
            end else if (req1 && !grant0 && last_granted == 1'b0) begin
                grant0 <= 1'b0;
                grant1 <= 1'b1;
                last_granted <= 1'b1;
            end else begin
                grant0 <= 1'b0;
                grant1 <= 1'b0;
            end
        end
    end
endmodule

module freq_divider #(parameter DIV_FACTOR = 2) (
    input clk,
    input reset,
    output reg out_clk
);
    reg [31:0] count;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            count <= 0;
            out_clk <= 0;
        end else begin
            if (count == (DIV_FACTOR - 1)) begin
                out_clk <= ~out_clk;
                count <= 0;
            end else begin
                count <= count + 1;
            end
        end
    end
endmodule

module restoring_divider(
    input clk,
    input reset,
    input [3:0] dividend,
    input [1:0] divisor,
    output reg [3:0] quotient,
    output reg [1:0] remainder,
    output reg done
);
    reg [3:0] temp_dividend;
    reg [1:0] temp_divisor;
    reg [2:0] count;
    reg [3:0] subtract_result;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            quotient <= 4'b0000;
            remainder <= 2'b00;
            temp_dividend <= 4'b0000;
            temp_divisor <= 2'b00;
            count <= 3'b000;
            done <= 0;
        end else begin
            if (count < 4) begin
                temp_dividend <= {temp_dividend[2:0], dividend[count]};
                subtract_result = temp_dividend - {2'b00, divisor};
                if (subtract_result[3] == 0) begin
                    temp_dividend <= subtract_result[3:0];
                    quotient <= {quotient[2:0], 1'b1};
                end else begin
                    quotient <= {quotient[2:0], 1'b0};
                end
                count <= count + 1;
            end else begin
                remainder <= temp_dividend[1:0];
                done <= 1;
            end
        end
    end
endmodule

module master_slave_d_latch (  
    input D,  
    input CLK,  
    output reg Q,  
    output reg Qn  
);  
    reg master_Q;  
    always @(posedge CLK) begin  
        master_Q <= D;  
    end  
    always @(negedge CLK) begin  
        Q <= master_Q;  
        Qn <= ~master_Q;  
    end  
endmodule

module pcie_fifo (  
    input wire clk,  
    input wire rst,  
    input wire wr_en,  
    input wire rd_en,  
    input wire [31:0] din,  
    output reg [31:0] dout,  
    output reg empty,  
    output reg full  
);  

    reg [31:0] fifo_mem [7:0];  
    reg [2:0] wr_ptr;  
    reg [2:0] rd_ptr;  
    reg [3:0] count;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            wr_ptr <= 3'b000;  
            rd_ptr <= 3'b000;  
            count <= 4'b0000;  
            empty <= 1;  
            full <= 0;  
        end else begin  
            if (wr_en && !full) begin  
                fifo_mem[wr_ptr] <= din;  
                wr_ptr <= wr_ptr + 1;  
                count <= count + 1;  
            end  

            if (rd_en && !empty) begin  
                dout <= fifo_mem[rd_ptr];  
                rd_ptr <= rd_ptr + 1;  
                count <= count - 1;  
            end  

            empty <= (count == 0);  
            full <= (count == 8);  
        end  
    end  
endmodule

module convolutional_encoder (
    input wire clk,
    input wire reset,
    input wire data_in,
    output reg data_out1,
    output reg data_out2
);
    reg [2:0] state;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= 3'b000; // Initialize state to zero
            data_out1 <= 0;
            data_out2 <= 0;
        end else begin
            // Shift and compute outputs
            state <= {state[1:0], data_in}; // Shift in new data

            // Compute outputs based on the current state
            data_out1 <= state[2] ^ state[1] ^ state[0]; // g1
            data_out2 <= state[2] ^ state[0]; // g2
        end
    end
endmodule

module srt_divider (
    input clk,
    input rst,
    input start,
    input [15:0] dividend,
    input [15:0] divisor,
    output reg [15:0] quotient,
    output reg [15:0] remainder,
    output reg done
);
    reg [15:0] A, Q, M;
    reg [4:0] count;
    reg state;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            A <= 16'b0;
            Q <= 16'b0;
            M <= 16'b0;
            quotient <= 16'b0;
            remainder <= 16'b0;
            done <= 0;
            count <= 5'b0;
            state <= 0;
        end else if (start) begin
            A <= dividend;
            M <= divisor;
            Q <= 16'b0;
            count <= 5'd16;
            state <= 1;
            done <= 0;
        end else if (state) begin
            if (count > 0) begin
                A <= {A[14:0], Q[15]};
                Q <= Q << 1;
                if (A >= M) begin
                    A <= A - M;
                    Q[0] <= 1;
                end else begin
                    Q[0] <= 0;
                end
                count <= count - 1;
            end else begin
                quotient <= Q;
                remainder <= A;
                done <= 1;
                state <= 0;
            end
        end
    end
endmodule

