module zero_crossing_detector(
    input clk,
    input rst,
    input signed [7:0] signal,
    output reg zero_cross
);

reg signed [7:0] prev_signal;

always @(posedge clk or posedge rst) begin
    if (rst) begin
        prev_signal <= 8'b0;
        zero_cross <= 1'b0;
    end else begin
        zero_cross <= (prev_signal[7] != signal[7]) && (signal != 8'b0);
        prev_signal <= signal;
    end
end

endmodule

