    initial begin
        // Initialize the hash values (first 32 bits of the fractional parts of the square roots of the first 64 primes)
        h[0] = 32'h6a09e667;
        h[1] = 32'hbb67ae85;
        h[2] = 32'h3c6ef372;
        h[3] = 32'ha54ff53a;
        h[4] = 32'h510e527f;
        h[5] = 32'h9b05688c;
