module uart_tx (
    input wire clk,
    input wire reset,
    input wire [4:0] data_in,
    input wire start_tx,
    output reg tx,
    output reg busy
);
    reg [3:0] bit_index;
    reg [9:0] shift_reg;

    localparam IDLE = 2'b00,
               START = 2'b01,
               TRANSMIT = 2'b10,
               STOP = 2'b11;

    reg [1:0] state, next_state;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
            busy <= 0;
        end else begin
            state <= next_state;
        end
    end

    always @* begin
        next_state = state;
        case (state)
            IDLE: begin
                tx = 1; // idle state is high
                if (start_tx) begin
                    shift_reg = {1'b1, data_in, 1'b0}; // stop, data, start
                    bit_index = 0;
                    next_state = START;
                    busy = 1;
                end
            end

            START: begin
                tx = 0; // start bit
                next_state = TRANSMIT;
            end

            TRANSMIT: begin
                tx = shift_reg[bit_index + 1]; // transmit bit
                if (bit_index < 5) begin
                    bit_index = bit_index + 1;
                end else begin
                    next_state = STOP; // after all bits are sent
                end
            end

            STOP: begin
                tx = 1; // stop bit
                busy = 0;
                next_state = IDLE;
            end

            default: next_state = IDLE; // safe default
        endcase
    end
endmodule

