module ofdm_modulator(  
    input clk,  
    input reset,  
    input [3:0] data_in,  
    input valid,  
    output reg [15:0] ifft_out,  
    output reg data_out_valid  
);  
    reg [3:0] freq_data [0:3]; // 4 subcarriers  
    reg [1:0] count;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            count <= 0;  
            data_out_valid <= 0;  
            ifft_out <= 0;  
        end else if (valid) begin  
            freq_data[count] <= data_in;  
            count <= count + 1;  
            if (count == 3) begin  
                // Simple IFFT operation (hardcoded for 4 subcarriers)  
                ifft_out <= freq_data[0] + freq_data[1] + freq_data[2] + freq_data[3];  
                data_out_valid <= 1;  
                count <= 0;  
            end  
        end  
    end  
endmodule

